Record GXR : Prop := MKGXR {
  x_gcx : gcx i c cells t l d g = true;
  x_push : match g with
           | PSO.GPush s1 s2 => ((Z.eqb s2 3 && PSO.expectb s1 && Z.eqb (PSOX.vpx i) s1) || (Z.eqb s2 28 && Z.eqb s1 5 && Z.eqb (PSOX.vpx i) 5)) && byteb s1
           | PSO.GStep s1 s2 => byteb s1 && byteb s2
           | _ => true end = true;
  x_ec0 : implb (PSO.is_ptk (PSO.kind_of i) && code0k (PSO.kind_of j)) (ec0 (CC.cp_nx c) cells t) = true;
  x_more0 : implb (PSO.kind_eqb (PSO.kind_of i) PSO.KSetec && match g with PSO.GSame => true | _ => false end) (more0 cells l) = true;
  x_smse : implb (PSO.kind_eqb (PSO.kind_of i) PSO.KSm && PSO.kind_eqb (PSO.kind_of j) PSO.KSe) (PSO.ne_acc cells) = true;
  x_smrx : implb (PSO.kind_eqb (PSO.kind_of i) PSO.KSm && PSO.kind_eqb (PSO.kind_of j) PSO.KRetx && match g with PSO.GSame => true | _ => false end) (PSO.lo_ge cells (EVar JV) 1) = true;
  x_pin : implb (PSO.u0 i && PSO.kind_eqb (PSO.kind_of j) PSO.KRetx && (PSO.is_ptk (PSO.kind_of i) || PSO.kind_eqb (PSO.kind_of i) PSO.KPop)) (pin1728 cells) = true;
  x_curh : implb (Z.eqb (PSO.d_adv d) 1) (expr_eqb (PSO.v_wptr t) PSO.CURH) = true;
  x_bb : implb (PSO.has_bufbyte (CC.cp_F c)) match g with PSO.GStop | PSO.GAccept | PSO.GPush _ _ => true | _ => false end = true;
  x_m1 : match g with
         | PSO.GStep _ _ => (PSO.is_same (PSO.d_more d) && PSO.rng_in cells (PSO.v_more l) 1 255) || PSO.rng_in (CC.cp_know c) (PSO.v_more t) 1 255
                            || PSO.kind_eqb (PSO.kind_of i) PSO.KErrh
         | PSO.GAccept => PSO.rng_in (CC.cp_know c) (PSO.v_more t) 1 255
         | _ => true end = true;
  x_lvl : match g with PSO.GStep _ 7 => expr_eqb (PSO.v_level t) (EVar LEVELV) && PSO.rng_in cells (EVar LEVELV) 1 (2 ^ 32 - 1) | _ => true end = true;
  x_stop : implb (match g with PSO.GStop => true | _ => false end && PSO.kind_eqb (PSO.kind_of j) PSO.KRetx)
                 (PSO.kind_eqb (PSO.kind_of i) PSO.KSetec || (PSO.kind_eqb (PSO.kind_of i) PSO.KSm && match PSO.st0pin cells with Some 29 => true | _ => false end)) = true;
  x_213 : (PSO.has cells (KWord (SA PE 213) 1 (ELit 1)) || negb (existsb (PSO.region_eqb (PE, 200, ELit 16)) (CC.cp_F c))) = true;
  x_cur : implb (PSO.curk (PSO.kind_of i)) (expr_eqb (PSO.v_wptr l) (nth 10 (CC.cp_regs c) (ELit 0))) = true;
  x_fl : expr_eqb (CC.slook s 60) FLE = true;
  x_q : implb ((PSO.kind_eqb (PSO.kind_of j) PSO.KHQ || PSO.kind_eqb (PSO.kind_of j) PSO.KLQ) && match g with PSO.GSame => true | _ => false end) (negb (Z.eqb (PSO.d_adv d) 1)) = true;
  x_u0 : implb (PSO.u0 i) (PSO.kind_eqb (PSO.kind_of j) PSO.KRetx || PSO.kind_eqb (PSO.kind_of j) PSO.KSe || PSO.kind_eqb (PSO.kind_of i) PSO.KSm) = true;
  x_ptq : implb (PSO.is_ptk (PSO.kind_of i) && (PSO.kind_eqb (PSO.kind_of j) PSO.KLQ || PSO.kind_eqb (PSO.kind_of j) PSO.KLZ)) (PSO.kind_eqb (PSO.kind_of i) (PSO.KPt PNUMBER)) = true;
  x_u0pt : implb (PSO.u0 i && PSO.is_ptk (PSO.kind_of i)) (PSO.kind_eqb (PSO.kind_of i) (PSO.KPt ENDINT) || PSO.kind_eqb (PSO.kind_of i) (PSO.KPt ENDFRAC)) = true;
  x_gs : implb (match g with PSO.GSame => true | _ => false end) (negb (PSO.kind_eqb (PSO.kind_of i) PSO.KPop || PSO.kind_eqb (PSO.kind_of i) PSO.KVpush)) = true;
  x_u0rx : implb (PSO.u0 i && PSO.kind_eqb (PSO.kind_of j) PSO.KRetx)
                 (PSO.kind_eqb (PSO.kind_of i) PSO.KSm || PSO.kind_eqb (PSO.kind_of i) PSO.KSetec || PSO.is_ptk (PSO.kind_of i) || PSO.kind_eqb (PSO.kind_of i) PSO.KPop) = true;
  x_u0se : implb (PSO.u0 i && PSO.kind_eqb (PSO.kind_of j) PSO.KSe) (PSO.kind_eqb (PSO.kind_of i) PSO.KSm) = true;
  x_acc : implb (match g with PSO.GAccept => true | _ => false end) (PSO.kind_eqb (PSO.kind_of i) PSO.KH || PSO.kind_eqb (PSO.kind_of i) PSO.KHQ || PSO.kind_eqb (PSO.kind_of i) PSO.KSm) = true;
  x_step : implb (match g with PSO.GStep _ _ => true | _ => false end) (negb (PSO.kind_eqb (PSO.kind_of i) PSO.KPop || PSO.kind_eqb (PSO.kind_of i) PSO.KVpush)) = true;
  x_rx : implb (PSO.kind_eqb (PSO.kind_of j) PSO.KRetx) (rxok2 i (CC.cp_nx c) cells t l) = true;
  x_pb : negb (PSO.kind_eqb (PSO.kind_of i) PSO.KPushb) = true;
  x_ics : match g with PSO.GStep s1 s2 => (negb (PSSC.icsb s2) || PSSC.icsb s1 || Z.eqb s2 7) | _ => true end = true;
  x_vis : implb (PSO.kind_eqb (PSO.kind_of i) PSO.KVis)
                (match g, PSO.tst c cells t, PSO.d_st d with
                 | PSO.GStop, Some s1, PSO.Lit s2 => byteb s1 && byteb s2 &&
                     (negb (Z.eqb s2 7) || (expr_eqb (PSO.v_level t) (EVar LEVELV) && PSO.rng_in cells (EVar LEVELV) 1 (2 ^ 32 - 1)))
                 | _, _, _ => false end) = true }.
