Lemma TRANS : forall mw ps1 code g1 st2 sst2 nst2 (more2 done2 : bool),
  PSOX.CORE I i Ec Mc mw ps1 code g1 ->
  Z_to_bv 8 (CL5A.uv El (PSO.v_st l)) = Z_to_bv 8 st2 -> Z_to_bv 8 (CL5A.uv El (PSO.v_sst l)) = Z_to_bv 8 sst2 ->
  Z_to_bv 8 (CL5A.uv El (PSO.v_nst l)) = Z_to_bv 8 nst2 -> Z_to_bv 8 (CL5A.uv El (PSO.v_more l)) = Z_to_bv 8 (PML.b2z more2) ->
  Z_to_bv 8 (CL5A.uv El (PSO.v_done l)) = Z_to_bv 8 (PML.b2z done2) ->
  (forall buf2 w2, PML.buf_need (PSOST.ps_upd ps1 st2 sst2 nst2 more2 done2 buf2 w2) <= PML.buf_need ps1) ->
  (PSOX.retk (PSO.kind_of j) = false -> PSOI.st0 I <> PML.ST_ACCEPT) ->
  (PSOX.wlk (PSO.kind_of j) = true -> 1 <= PSOI.wlen I) ->
  (more2 = true -> PML.ps_more ps1 = true) ->
  exists buf2 w2, PSOX.CORE I j Ej Ml w2 (PSOST.ps_upd ps1 st2 sst2 nst2 more2 done2 buf2 w2) code g1 /\
    length buf2 = length (PML.ps_buf ps1) /\ (PSO.has_bufbyte (CC.cp_F c) = false -> buf2 = PML.ps_buf ps1) /\
    (PSO.d_adv d <> 1 -> w2 = PML.ps_win ps1) /\
